import 'dart:convert';import 'package:flutter/material.dart';
class Mark{final String subject;final int score;Mark(this.subject,this.score);Map<String,dynamic>toJson()=>{'subject':subject,'score':score};factory Mark.fromJson(Map<String,dynamic>j)=>Mark(j['subject'],j['score']);}
class Student{final String name;final int roll;final List<Mark>marks;Student(this.name,this.roll,this.marks);Map<String,dynamic>toJson()=>{'name':name,'roll':roll,'marks':marks.map((e)=>e.toJson()).toList()};factory Student.fromJson(Map<String,dynamic>j)=>Student(j['name'],j['roll'],(j['marks']as List).map((e)=>Mark.fromJson(e)).toList());}
void main(){final s=Student('Jadav Tushar',15,[Mark('Flutter',90),Mark('Dart',92)]);final json=jsonEncode(s.toJson());final restored=Student.fromJson(jsonDecode(json));runApp(MaterialApp(home:Scaffold(appBar:AppBar(title:const Text('Nested JSON')),body:Padding(padding:const EdgeInsets.all(16),child:Text('JSON: $json\n\nRestored: ${restored.name} - ${restored.marks.first.subject}: ${restored.marks.first.score}')))));}
